import assert from "node:assert/strict";
import crypto from "node:crypto";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { describe, it } from "@jest/globals";
import { buildArtifacts, excludedRuleIds, excludedRuleReasons, machinePath, packetDir, selectedRuleIds, writeArtifacts } from "../../../scripts/preverif/generate-rc5-maya-wave1-pdd-finality";

const sha = (v: string | Buffer) => crypto.createHash("sha256").update(v).digest("hex");
const root = process.cwd();
describe("RC5-2 Maya Wave 1 PDD finality packet", () => {
  it("derives exactly 48/10/58 and selects only current provisional rules", () => { const a = buildArtifacts(); assert.deepEqual(a.packet.frozenInventory, { totalRules: 58, uniqueRuleCount: 58, reviewedRuleCount: 48, provisionalRuleCount: 10, provisionalRuleIds: [...selectedRuleIds, ...excludedRuleIds].sort(), selectedRuleIds, excludedRuleIds }); assert.equal(a.packet.rules.length, 8); });
  it("excludes the two genuinely attachment-dependent rules", () => { const a = buildArtifacts(); assert.deepEqual(excludedRuleIds, Object.keys(excludedRuleReasons)); assert.ok(Object.values(excludedRuleReasons).every((reason) => /absent|missing/i.test(reason))); assert.ok(excludedRuleIds.every((id) => !a.packet.selectedRuleIds.includes(id))); });
  it("does not leak current human blocker language into packet metadata", () => { const packet = JSON.stringify(buildArtifacts().packet); for (const phrase of ["Boundary coordinates and shapefile/KML references are provided", "The proxy similarity analysis is documented", "The PDD does not yet show", "prior reviewer conclusion"]) assert.equal(packet.includes(phrase), false, phrase); for (const rule of buildArtifacts().packet.rules as any[]) { assert.deepEqual(Object.keys(rule.currentMachineOnlySummary).sort(), ["proposedApplicability", "proposedEvidenceStatus", "upstreamStatus"].sort()); for (const field of ["assessmentReason", "gap", "clientAction", "reviewHistory", "finalizationState"]) assert.equal(field in rule.frozenMachineRow, false, field); } });
  it("pins exact evidence, machine rows, and source mutations", () => { const a = buildArtifacts(); const machine = JSON.parse(fs.readFileSync(path.join(root, machinePath), "utf8")); for (const rule of a.packet.rules as any[]) { const originalRow = machine.rows.find((row: any) => row.stableRuleId === rule.stableRuleId); assert.equal(rule.machineRowSha256, sha(JSON.stringify(originalRow))); for (const e of rule.fullRelevantPddPageContexts) assert.equal(e.documentSha256, a.packet.sourceDocument.contentSha256); for (const e of rule.candidateEvidence) assert.equal(e.documentSha256, a.packet.sourceDocument.contentSha256); } const mutated = JSON.parse(JSON.stringify(a.packet)); mutated.rules[0].frozenMachineRow.stableRuleId = "mutated"; assert.notEqual(mutated.rules[0].machineRowSha256, sha(JSON.stringify(mutated.rules[0].frozenMachineRow))); const original = fs.readFileSync(path.join(root, machinePath)); try { fs.writeFileSync(path.join(root, machinePath), Buffer.concat([original, Buffer.from("\n")])) ; assert.throws(() => buildArtifacts(), /machine|SHA|source/i); } finally { fs.writeFileSync(path.join(root, machinePath), original); } });
  it("uses the pinned pre-integration reviewed-truth source", () => { const a = buildArtifacts(); assert.equal(a.sourceArtifacts.mainBaseCommitSha, "39ff42ecdb102d98ad4801c2cd483f43d75b8f32"); assert.equal(Object.keys(a.sourceArtifacts.reviewedTruthForSelectionOnly).length, 6); });
  it("regenerates byte-for-byte and preserves blank response template", () => { const a = buildArtifacts(); const dir = fs.mkdtempSync(path.join(os.tmpdir(), "maya-wave1-")); try { const generated = writeArtifacts(dir); for (const file of ["review-packet.json", "review-response-schema.json", "review-template.json", "reviewer-instructions.md", "manifest.json"]) assert.equal(fs.readFileSync(path.join(dir, file), "utf8"), fs.readFileSync(path.join(packetDir, file), "utf8"), file); assert.ok(generated.template.decisions.every((d: any) => d.acceptedEvidence.length === 0 && d.rejectedEvidence.length === 0)); } finally { fs.rmSync(dir, { recursive: true, force: true }); } });
  it("keeps reviewed and machine truth unchanged", () => { assert.equal(sha(fs.readFileSync(path.join(root, machinePath))), "e996de2eef1fc80aefa94e723903049ae4451fb161baccf337750694a394479b"); for (const file of buildArtifacts().sourceArtifacts.reviewedTruthForSelectionOnly ? Object.keys(buildArtifacts().sourceArtifacts.reviewedTruthForSelectionOnly) : []) assert.ok(fs.existsSync(path.join(root, file))); });
});
